const $=s=>document.querySelector(s),view=$("#view"),KEY="hg-studio-projects-v1",ACTIVE="hg-studio-active-v1";
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
let storeOk=true,projects=[],active="",route="home",moduleId="design",visionFile=null,upscaleFile=null,planFile=null,visionData=null,upscaleUrl=null,toastTimer=null;
function seed(){try{let raw=JSON.parse(localStorage.getItem(KEY)||"[]");projects=Array.isArray(raw)?raw.filter(validateProject).slice(0,80):[];active=localStorage.getItem(ACTIVE)||"";}catch(e){storeOk=false;projects=[];}if(!projects.length){projects=[newProject("Dự án đầu tiên")];save();}if(!projects.some(p=>p.id===active))active=projects[0].id;}
function project(){return projects.find(p=>p.id===active)||projects[0];}
function save(){try{localStorage.setItem(KEY,JSON.stringify(projects));localStorage.setItem(ACTIVE,active);storeOk=true;}catch(e){storeOk=false;notify("Bộ nhớ đầy hoặc bị chặn. Hãy xuất bản sao JSON.");}}
function touch(){project().updated=new Date().toISOString();save();}
function notify(msg){let t=$("#toast");t.textContent=msg;t.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove("show"),3700);}
function download(text,name,mime="text/plain;charset=utf-8"){let url=URL.createObjectURL(new Blob([text],{type:mime}));let a=document.createElement("a");a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200);}
const VI_OPTIONS={"create":"Tạo thiết kế mới","edit":"Chỉnh sửa / đồng bộ","yes":"Có","no":"Không","Natural Daylight":"Ánh sáng tự nhiên ban ngày","Slow Dolly":"Máy quay tiến chậm","Orbit":"Quay vòng quanh","Tracking":"Di chuyển bám theo","Static":"Máy quay cố định","Crane":"Nâng hạ máy quay","Push In":"Tiến gần","Furniture / Citterio":"Chuyên gia nội thất / Citterio","Material / Zumthor":"Chuyên gia vật liệu / Zumthor","Lighting / Ingo Maurer":"Chuyên gia ánh sáng / Ingo Maurer","Camera / Iwan Baan":"Chuyên gia góc máy / Iwan Baan","Removal":"Loại bỏ đối tượng","AspectRatio":"Tỷ lệ khung hình","ReferenceReplica":"Tái tạo theo ảnh tham chiếu","SpaceSync":"Đồng bộ không gian","Storyboard":"Kịch bản phân cảnh","Minimal Luxury":"Sang trọng tối giản","Contemporary":"Đương đại","Modern":"Hiện đại","Neo Classic":"Tân cổ điển","Wabi-Sabi":"Mộc mạc Wabi-Sabi","Japandi":"Nhật Bản – Bắc Âu","Luxury":"Sang trọng","Bauhaus":"Bauhaus","Biophilic":"Thiết kế gần thiên nhiên","Tropical Coastal":"Nhiệt đới ven biển","Industrial":"Công nghiệp","Classic":"Cổ điển"};
const viOption=x=>VI_OPTIONS[x]||x;
function field(label,name,value="",opts=null,hint=""){const id="f-"+name;if(opts){return '<div class="field"><label for="'+id+'">'+esc(label)+'</label><select id="'+id+'" data-field="'+esc(name)+'">'+opts.map(o=>'<option value="'+esc(o)+'" '+(o===value?"selected":"")+'>'+esc(viOption(o))+'</option>').join("")+'</select>'+(hint?'<small>'+esc(hint)+'</small>':"")+'</div>';}return '<div class="field"><label for="'+id+'">'+esc(label)+'</label>'+(name==="brief"||name==="notes"?'<textarea id="'+id+'" data-field="'+esc(name)+'" placeholder="Nhập yêu cầu rõ ràng...">'+esc(value)+'</textarea>':'<input id="'+id+'" data-field="'+esc(name)+'" value="'+esc(value)+'" placeholder="'+esc(label)+'">')+(hint?'<small>'+esc(hint)+'</small>':"")+'</div>';}
function header(tag,title,subtitle,extra=""){return '<div class="hero"><div><span class="eyebrow">'+esc(tag)+'</span><h1>'+esc(title)+'</h1><p>'+esc(subtitle)+'</p></div>'+extra+'</div>';}
function statusBadge(s){return '<span class="pill '+(s==="limited"?"limit":s==="planned"?"planned":"")+'">'+(s==="planned"?"Chưa kết nối":s==="limited"?"Giới hạn":"Công cụ nội bộ")+'</span>';}
